//! Independent-oracle tests (COL-002, COL-003, COL-008).
//!
//! Expectations come from `tests/fixtures/color/expected_conversions.json`, generated by
//! `scripts/color/gen_oracle_fixtures.py` with LittleCMS (via Pillow ImageCms) and colour-science.
//! Run with `-- --nocapture` to see the measured numbers. With `VESKRA_WRITE_COLOR_REPORT=1` the
//! test `color_report` (re)writes `tests/fixtures/color/color_report.json` from the values it
//! measured in that run.
//!
//! Percentiles: median = mean of the two middle values for even n; p95 = nearest-rank
//! (`ceil(0.95·n)`-th smallest).

// Test-only code: fixture/IO failures should abort the test loudly.
#![allow(clippy::unwrap_used, clippy::needless_range_loop)]

use serde::Deserialize;
use serde_json::json;
use std::collections::BTreeMap;
use std::path::PathBuf;
use std::sync::Arc;
use veskra_color::icc::IccProfile;
use veskra_color::lab::{ciede2000, profile_rgb_to_lab_d50, srgb8_to_lab_d50};
use veskra_color::transform::{RenderingIntent, RgbTransform, TransformOptions};

#[derive(Deserialize)]
struct Doc {
    tools: BTreeMap<String, String>,
    profiles: BTreeMap<String, ProfileInfo>,
    swatches: Vec<Swatch>,
    conversions: Vec<Conversion>,
    ciede2000_sharma: Vec<SharmaRow>,
    ciede2000_swatch_pairs: Vec<Pair>,
}

#[derive(Deserialize)]
struct ProfileInfo {
    file: String,
    sha256: String,
    lcms_open_ok: bool,
    lcms_description: String,
    lcms_colorants: [[f64; 3]; 3],
    md5_profile_id_ok: bool,
}

#[derive(Deserialize)]
struct Swatch {
    rgb8: [u8; 3],
    lab_d50_srgb: [f64; 3],
    lab_d50_if_p3: [f64; 3],
    colour_srgb_to_p3_float: [f64; 3],
}

#[derive(Deserialize)]
struct Conversion {
    name: String,
    src: String,
    dst: String,
    intent: String,
    lcms_flags: String,
    output8: Vec<[u8; 3]>,
}

#[derive(Deserialize)]
struct SharmaRow {
    lab1: [f64; 3],
    lab2: [f64; 3],
    colour: f64,
}

#[derive(Deserialize)]
struct Pair {
    i: usize,
    j: usize,
    de00: f64,
}

fn fixtures() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/color")
}

fn load() -> Doc {
    let p = fixtures().join("expected_conversions.json");
    let text = std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()));
    serde_json::from_str(&text).unwrap()
}

fn profile(doc: &Doc, key: &str) -> Arc<IccProfile> {
    match key {
        "veskra_srgb" => IccProfile::srgb(),
        "veskra_p3" => IccProfile::display_p3(),
        other => {
            let info = &doc.profiles[other];
            Arc::new(IccProfile::parse(&std::fs::read(fixtures().join(&info.file)).unwrap()).unwrap())
        }
    }
}

fn intent(s: &str) -> RenderingIntent {
    match s {
        "perceptual" => RenderingIntent::Perceptual,
        "saturation" => RenderingIntent::Saturation,
        "absolute-colorimetric" => RenderingIntent::AbsoluteColorimetric,
        _ => RenderingIntent::RelativeColorimetric,
    }
}

#[derive(Debug, Clone, Copy)]
struct Stats {
    n: usize,
    median: f64,
    p95: f64,
    max: f64,
}

fn stats(mut v: Vec<f64>) -> Stats {
    assert!(!v.is_empty());
    v.sort_by(f64::total_cmp);
    let n = v.len();
    let median = if n % 2 == 1 { v[n / 2] } else { (v[n / 2 - 1] + v[n / 2]) / 2.0 };
    let rank = (0.95 * n as f64).ceil() as usize;
    Stats { n, median, p95: v[rank.clamp(1, n) - 1], max: v[n - 1] }
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

fn apply8(t: &RgbTransform, rgb: &[[u8; 3]]) -> Vec<[u8; 3]> {
    let mut buf: Vec<u8> = rgb.iter().flat_map(|c| [c[0], c[1], c[2], 255]).collect();
    t.apply_rgba8_straight(&mut buf);
    buf.chunks_exact(4).map(|p| [p[0], p[1], p[2]]).collect()
}

/// Veskra vs LittleCMS for one conversion: (max 8-bit channel diff, ΔE00 stats in dst profile).
struct Agreement {
    name: String,
    src: Arc<IccProfile>,
    dst: Arc<IccProfile>,
    intent: String,
    flags: String,
    max_diff: u8,
    exact_fraction: f64,
    de: Stats,
}

fn agreements(doc: &Doc) -> Vec<Agreement> {
    let inputs: Vec<[u8; 3]> = doc.swatches.iter().map(|s| s.rgb8).collect();
    doc.conversions
        .iter()
        .map(|c| {
            let (src, dst) = (profile(doc, &c.src), profile(doc, &c.dst));
            let t = RgbTransform::new(&src, &dst, intent(&c.intent)).unwrap();
            let ours = apply8(&t, &inputs);
            assert_eq!(ours.len(), c.output8.len());
            let mut max_diff = 0u8;
            let mut exact = 0usize;
            let mut de = Vec::new();
            for (o, l) in ours.iter().zip(&c.output8) {
                let d = (0..3).map(|i| o[i].abs_diff(l[i])).max().unwrap_or(0);
                max_diff = max_diff.max(d);
                exact += usize::from(d == 0);
                let lab = |p: &[u8; 3]| profile_rgb_to_lab_d50(&dst, p.map(|v| v as f64 / 255.0));
                de.push(ciede2000(lab(o), lab(l)));
            }
            Agreement {
                name: c.name.clone(),
                src,
                dst,
                intent: c.intent.clone(),
                flags: c.lcms_flags.clone(),
                max_diff,
                exact_fraction: exact as f64 / ours.len() as f64,
                de: stats(de),
            }
        })
        .collect()
}

#[test]
fn fixture_was_generated_from_current_profiles_and_lcms_accepts_them() {
    let doc = load();
    assert!(doc.swatches.len() >= 128, "COL-003 needs >= 128 samples");
    for (key, p) in [("veskra_srgb", IccProfile::srgb()), ("veskra_p3", IccProfile::display_p3())] {
        let info = &doc.profiles[key];
        assert_eq!(info.sha256, hex(&p.id().icc_hash), "{key}: regenerate oracle fixtures");
        assert!(info.lcms_open_ok && info.md5_profile_id_ok, "{key}");
        assert_eq!(info.lcms_description, p.description());
        // LittleCMS reads exactly the colorants Veskra wrote (12 significant digits in JSON).
        let m = p.to_xyz_d50_matrix();
        for (c, col) in info.lcms_colorants.iter().enumerate() {
            for r in 0..3 {
                assert!((col[r] - m[r][c]).abs() < 1e-11, "{key} colorant {c},{r}");
            }
        }
    }
    // Third-party sRGB (LittleCMS built-in) is recognized as sRGB-equivalent.
    let lcms = profile(&doc, "lcms_builtin_srgb");
    assert!(lcms.is_srgb_equivalent());
    assert_eq!(lcms.id().semantic_name, "sRGB IEC61966-2.1");
    assert!(
        RgbTransform::new(&lcms, &IccProfile::srgb(), RenderingIntent::RelativeColorimetric).unwrap().is_identity()
    );
}

#[test]
fn lab_matches_colour_science() {
    let doc = load();
    let mut max_srgb: f64 = 0.0;
    let mut max_p3_profile: f64 = 0.0;
    for s in &doc.swatches {
        let ours = srgb8_to_lab_d50(s.rgb8);
        for i in 0..3 {
            max_srgb = max_srgb.max((ours[i] - s.lab_d50_srgb[i]).abs());
        }
        // Through the generated (s15Fixed16-quantized) P3 profile.
        let p3 = profile_rgb_to_lab_d50(&IccProfile::display_p3(), s.rgb8.map(|v| v as f64 / 255.0));
        for i in 0..3 {
            max_p3_profile = max_p3_profile.max((p3[i] - s.lab_d50_if_p3[i]).abs());
        }
    }
    println!(
        "Lab vs colour-science: exact sRGB path max |dLab| = {max_srgb:.3e}; P3 ICC path max |dLab| = {max_p3_profile:.3e}"
    );
    assert!(max_srgb < 1e-6, "{max_srgb}");
    assert!(max_p3_profile < 1e-2, "{max_p3_profile}");
}

#[test]
fn ciede2000_matches_colour_science() {
    let doc = load();
    let mut worst: f64 = 0.0;
    for r in &doc.ciede2000_sharma {
        worst = worst.max((ciede2000(r.lab1, r.lab2) - r.colour).abs());
    }
    for p in &doc.ciede2000_swatch_pairs {
        let d = ciede2000(doc.swatches[p.i].lab_d50_srgb, doc.swatches[p.j].lab_d50_srgb);
        worst = worst.max((d - p.de00).abs());
    }
    println!(
        "CIEDE2000 vs colour-science: {} pairs, max |diff| = {worst:.3e}",
        doc.ciede2000_sharma.len() + doc.ciede2000_swatch_pairs.len()
    );
    assert!(worst < 1e-9, "{worst}");
}

#[test]
fn float_transform_matches_colour_science() {
    let doc = load();
    let t = RgbTransform::new(&IccProfile::srgb(), &IccProfile::display_p3(), RenderingIntent::RelativeColorimetric)
        .unwrap();
    let mut worst: f64 = 0.0;
    let mut at = [0u8; 3];
    for s in &doc.swatches {
        let ours = t.apply_f64(s.rgb8.map(|v| v as f64 / 255.0));
        for i in 0..3 {
            let d = (ours[i] - s.colour_srgb_to_p3_float[i]).abs();
            if d > worst {
                worst = d;
                at = s.rgb8;
            }
        }
    }
    println!(
        "sRGB->P3 float vs colour-science: max |diff| = {worst:.3e} (= {:.4} 8-bit LSB) at sRGB {at:?}",
        worst * 255.0
    );
    // Only the ICC s15Fixed16 quantization of colorants and `para` parameters (as stored in the
    // profiles, identical for LittleCMS) separates the two; bound: 0.1 LSB at 8 bits.
    assert!(worst * 255.0 < 0.1, "{worst}");
}

#[test]
fn transforms_match_littlecms() {
    let doc = load();
    for a in agreements(&doc) {
        println!(
            "vs LittleCMS {:<62} max8={} exact={:.1}% dE00 median={:.4} p95={:.4} max={:.4}",
            a.name,
            a.max_diff,
            a.exact_fraction * 100.0,
            a.de.median,
            a.de.p95,
            a.de.max
        );
        assert!(a.max_diff <= 1, "{}: max 8-bit diff {}", a.name, a.max_diff);
        assert!(a.de.median <= 1.0 && a.de.p95 <= 2.0, "{}", a.name);
    }
}

fn col002() -> (u64, u8, u8) {
    let s = IccProfile::srgb();
    let fast = RgbTransform::new(&s, &s, RenderingIntent::RelativeColorimetric).unwrap();
    let full = RgbTransform::with_options(
        &s,
        &s,
        RenderingIntent::RelativeColorimetric,
        TransformOptions { detect_identity: false },
    )
    .unwrap();
    assert!(fast.is_identity() && !full.is_identity());
    let (mut max_fast, mut max_full) = (0u8, 0u8);
    let mut n = 0u64;
    let mut buf = vec![0u8; 256 * 256 * 4];
    for r in 0..=255u8 {
        for (i, p) in buf.chunks_exact_mut(4).enumerate() {
            p.copy_from_slice(&[r, (i >> 8) as u8, (i & 0xff) as u8, 255]);
        }
        let orig = buf.clone();
        let mut a = buf.clone();
        fast.apply_rgba8_straight(&mut a);
        full.apply_rgba8_straight(&mut buf);
        for ((x, y), o) in a.iter().zip(&buf).zip(&orig) {
            max_fast = max_fast.max(x.abs_diff(*o));
            max_full = max_full.max(y.abs_diff(*o));
        }
        n += 65536;
        buf = orig;
    }
    (n, max_fast, max_full)
}

#[test]
fn col002_srgb_8bit_identity_exhaustive() {
    let (n, fast, full) = col002();
    println!("COL-002: {n} sRGB 8-bit colors; identity passthrough max diff = {fast}; full pipeline max diff = {full}");
    assert_eq!(fast, 0);
    assert!(full <= 1);
}

/// COL-003 defined conversion: 8-bit sRGB swatch → Veskra sRGB→Display P3 (relative
/// colorimetric) → 8-bit P3, evaluated in Lab D50 via the generated P3 profile, compared with the
/// colour-science Lab D50 of the source sRGB swatch.
fn col003(doc: &Doc) -> Stats {
    let t = RgbTransform::new(&IccProfile::srgb(), &IccProfile::display_p3(), RenderingIntent::RelativeColorimetric)
        .unwrap();
    let inputs: Vec<[u8; 3]> = doc.swatches.iter().map(|s| s.rgb8).collect();
    let out = apply8(&t, &inputs);
    let p3 = IccProfile::display_p3();
    stats(
        out.iter()
            .zip(&doc.swatches)
            .map(|(o, s)| ciede2000(profile_rgb_to_lab_d50(&p3, o.map(|v| v as f64 / 255.0)), s.lab_d50_srgb))
            .collect(),
    )
}

#[test]
fn col003_swatches_in_common_lab() {
    let doc = load();
    let s = col003(&doc);
    println!("COL-003: n={} dE00 median={:.4} p95={:.4} max={:.4}", s.n, s.median, s.p95, s.max);
    assert!(s.median <= 1.0 && s.p95 <= 2.0);
}

#[test]
fn color_report() {
    let doc = load();
    let pass = |ok: bool| if ok { "PASS" } else { "FAIL" };
    let mut reports = Vec::new();

    let (n, fast, full) = col002();
    let srgb_name = IccProfile::srgb().id().semantic_name;
    for (fixture, diff, reference) in [
        ("srgb8_exhaustive_identity", fast, "exact input values (identity passthrough)"),
        ("srgb8_exhaustive_full_pipeline", full, "exact input values (identity detection disabled)"),
    ] {
        reports.push(json!({
            "check": "COL-002",
            "fixture": fixture,
            "input_profile": srgb_name,
            "output_profile": srgb_name,
            "intent": "relative-colorimetric",
            "samples": n,
            "median_deltaE00": null,
            "p95_deltaE00": null,
            "max_channel_diff_8bit": diff,
            "threshold": "max_channel_diff_8bit <= 1",
            "reference": reference,
            "status": pass(diff <= 1),
        }));
    }

    let s = col003(&doc);
    reports.push(json!({
        "check": "COL-003",
        "fixture": "srgb_swatches_v1",
        "input_profile": srgb_name,
        "output_profile": IccProfile::display_p3().id().semantic_name,
        "intent": "relative-colorimetric",
        "samples": s.n,
        "median_deltaE00": s.median,
        "p95_deltaE00": s.p95,
        "max_deltaE00": s.max,
        "threshold": "median_deltaE00 <= 1.0 && p95_deltaE00 <= 2.0",
        "reference": "colour-science Lab D50 (ICC D50 white, Bradford) of the source sRGB swatch; Veskra 8-bit P3 output evaluated through the generated P3 profile",
        "status": pass(s.median <= 1.0 && s.p95 <= 2.0),
    }));

    for a in agreements(&doc) {
        let ok = a.de.median <= 1.0 && a.de.p95 <= 2.0;
        reports.push(json!({
            "check": "COL-008",
            "fixture": "srgb_swatches_v1",
            "conversion": a.name,
            "input_profile": a.src.description(),
            "output_profile": a.dst.description(),
            "intent": a.intent,
            "samples": a.de.n,
            "median_deltaE00": a.de.median,
            "p95_deltaE00": a.de.p95,
            "max_deltaE00": a.de.max,
            "max_channel_diff_8bit": a.max_diff,
            "exact_match_fraction": a.exact_fraction,
            "threshold": "median_deltaE00 <= 1.0 && p95_deltaE00 <= 2.0 (COL-003 thresholds applied to Veskra vs LittleCMS)",
            "reference": format!("LittleCMS {} via Pillow ImageCms, flags {}", doc.tools["littlecms"], a.flags),
            "status": pass(ok),
        }));
    }

    let report = json!({
        "schema": "veskra-color-report/1 (entries follow VERIFICATION_MATRIX.md §4)",
        "generated_by": "crates/veskra-color/tests/oracle.rs::color_report",
        "oracle_tools": doc.tools,
        "deltaE_definition": "CIEDE2000 (kL=kC=kH=1) in CIELAB with ICC D50 white; median = mean of middle pair for even n; p95 = nearest rank",
        "reports": reports,
    });
    assert!(report["reports"].as_array().unwrap().iter().all(|r| r["status"] == "PASS"), "{report:#}");
    if std::env::var("VESKRA_WRITE_COLOR_REPORT").is_ok_and(|v| v == "1") {
        let text = serde_json::to_string_pretty(&report).unwrap() + "\n";
        std::fs::write(fixtures().join("color_report.json"), text).unwrap();
    }
}
